import assert from 'node:assert/strict'
import { readFileSync, writeFileSync } from 'node:fs'
import { resolve, dirname } from 'node:path'
const [input, output] = process.argv.slice(2)
if (!input || !output) throw new Error('Usage: node instrument-html-audit.mjs input-check.mjs output-check.mjs')
const destination = resolve(output)
if (destination === resolve(input)) throw new Error('Keep original checker unchanged')
if (dirname(destination) !== dirname(resolve(input))) throw new Error('Write test copy beside original so imports keep their meanings')
let source = readFileSync(input, 'utf8')
const replaceOnce = (before, after) => {
  assert.equal(source.split(before).length, 2, 'Unexpected checker shape: ' + before.slice(0, 70))
  source = source.replace(before, after)
}
replaceOnce('async function chat(cdp) {', 'async function chat(cdp, auditPort) {')
replaceOnce('await chat(cdp).then(', 'await chat(cdp, port).then(')
replaceOnce("const graphics = process.env.CI && process.platform === 'darwin' ? ['--disable-gpu'] : []", "const graphics = process.env.CHEMCLAW_HTML_GRAPHICS === 'software' ? ['--disable-gpu'] : []")
const anchor = "  await until(\"document.querySelector('iframe')\", 'the HTML preview')"
replaceOnce(anchor, anchor + "\n  await until(\"(()=>{const f=document.querySelector('iframe[data-html-preview]');const r=f?.getBoundingClientRect();return r?.width>100&&r?.height>100})()\", 'the visible HTML preview')\n  await auditHtmlFrame(cdp, auditPort, evaluate, shotFile)")
source += '\n' + "async function auditHtmlFrame(parent, port, evaluate, screenshotPrefix) {\n  const result = { platform: process.platform, arch: process.arch, graphics: process.env.CHEMCLAW_HTML_GRAPHICS || 'default' }\n  let child\n  try {\n    result.iframe = await evaluate(\"(()=>{const f=document.querySelector('iframe[data-html-preview]');if(!f)return null;const r=f.getBoundingClientRect();return {name:f.name,sandbox:f.getAttribute('sandbox'),src:f.getAttribute('src')||'',srcDoc:f.hasAttribute('srcdoc'),width:r.width,height:r.height}})()\")\n    if (!result.iframe || result.iframe.width < 100 || result.iframe.height < 100) throw new Error('No visible HTML preview frame')\n    if (result.iframe.sandbox !== 'allow-scripts') throw new Error('Fresh profile did not select interactive HTML')\n    const deadline = Date.now() + 30000\n    while (Date.now() < deadline) {\n      const targets = await (await fetch('http://127.0.0.1:' + port + '/json/list')).json()\n      const target = targets.find(target => target.type === 'iframe' && target.url === result.iframe.src)\n      if (target) {\n        const problems = []\n        child = devtools(target.webSocketDebuggerUrl, problems)\n        await child.opened\n        await child.call('Runtime.enable')\n        await child.call('Log.enable')\n        while (Date.now() < deadline) {\n          const snapshot = await child.call('DOMSnapshot.captureSnapshot', { computedStyles: ['display', 'visibility'], includeDOMRects: true })\n          result.body = snapshot.documents.flatMap(document => document.layout.text.map(index => snapshot.strings[index])).filter(Boolean).join('\\n')\n          if (result.body.includes('可点击交付文件')) break\n          await sleep(150)\n        }\n        if (!result.body?.includes('可点击交付文件')) throw new Error('HTML heading did not render')\n        const click = await child.call('Runtime.evaluate', { expression: \"document.querySelector('button').click();document.querySelector('button').textContent\", returnByValue: true, awaitPromise: true })\n        if (click.exceptionDetails) throw new Error(click.exceptionDetails.exception?.description || click.exceptionDetails.text)\n        result.button = click.result.value\n        if (result.button !== '交互成功') throw new Error('HTML inline click handler did not run')\n        if (problems.length) throw new Error('HTML iframe errors: ' + problems.join(' | '))\n        result.status = 'passed'\n        console.log('mac-html-audit: ' + JSON.stringify(result))\n        return\n      }\n      await sleep(150)\n    }\n    throw new Error('The isolated HTML iframe target was not available')\n  } catch (error) {\n    result.status = 'failed'\n    result.error = error.message\n    throw error\n  } finally {\n    if (screenshotPrefix) writeFileSync(resolve(screenshotPrefix + '.html-runtime.json'), JSON.stringify(result, null, 2) + '\\n')\n    if (child) await Promise.race([child.close(), sleep(1000)])\n  }\n}\n"
writeFileSync(destination, source, 'utf8')
console.log('Prepared test copy: ' + destination)
